def slugify(s):
    s = s.lower()
    # Transliterate special characters
    replacements = {
        'õ': 'o',
        'ä': 'a',
        'ö': 'o',
        'ü': 'u',
        'ä': 'a',
        'ß': 'ss',
        'ç': 'c',
    }
    for k, v in replacements.items():
        s = s.replace(k, v)

    out = []
    for ch in s:
        if ch.isalnum():
            out.append(ch)
        else:
            out.append('-')

    # Collapse consecutive dashes
    result = []
    for ch in out:
        if ch == '-' and (not result or result[-1] == '-'):
            continue
        result.append(ch)

    return ''.join(result).strip('-')

import unicodedata
import re


def slugify(s):
    s = unicodedata.normalize('NFD', s).lower()
    out = []
    for ch in s:
        if unicodedata.category(ch).startswith('M'):
            continue
        elif ch.isalnum():
            out.append(ch)
        else:
            out.append('-')
    return re.sub(r'-+', '-', ''.join(out)).strip('-')

